def cases():
    return json.loads(json.dumps(CASES))

def number(v):
    try:return float(v)
    except (TypeError,ValueError):return math.nan

def prepared(row):
    p=row['parameters'];source=p['records'];raw=[record[0] for record in source];mapping=p.get('time_map')
    if mapping and any(mapping.get(t) is not None for t in raw):times=[number(mapping.get(t)) for t in raw]
    else:
        times=[number(t) for t in raw]
        if not any(not math.isnan(t) for t in times):
            times=[number(m.group(0)) if (m:=re.search(r'\d+\.?\d*',str(t))) else math.nan for t in raw]
    result=[]
    for (_,y,g),t in zip(source,times):
        value=number(y)
        if math.isfinite(t) and math.isfinite(value) and g is not None:result.append((t,value,str(g)))
    return result

def core_mathematical(row):
    data=prepared(row);groups=list(dict.fromkeys(g for t,y,g in data));n=len(data);k=len(groups)
    if k<2 or n<3*k+1:return [math.nan,math.nan,0,0,n,k,*range(k)]
    with mp.workdps(80):
        w=2*mp.pi/mp.mpf(str(row['parameters']['period']));y=mp.matrix([mp.mpf(str(v)) for t,v,g in data])
        red=[];full=[]
        for t,value,g in data:
            angle=w*mp.mpf(str(t));cos=mp.cos(angle);sin=mp.sin(angle)
            indicator=[int(g==name) for name in groups]
            red.append([*indicator,cos,sin]);full.append([*indicator,*(v*cos for v in indicator),*(v*sin for v in indicator)])
        def fit(rows):
            X=mp.matrix(rows);U,s,V=mp.svd_r(X);threshold=mp.mpf('1e-60')*max(s)
            rank=sum(v>threshold for v in s);coefficients=mp.matrix(X.cols,1)
            for i,v in enumerate(s):
                if v>threshold:
                    coordinate=sum(U[j,i]*y[j] for j in range(n))/v
                    for j in range(X.cols):coefficients[j]+=V[i,j]*coordinate
            residual=y-X*coefficients;rss=sum(v*v for v in residual)
            if rss<mp.mpf('1e-60'):rss=mp.mpf(0)
            return rss,rank
        r_red,rank_red=fit(red);r_full,rank_full=fit(full)
        df1=rank_full-rank_red;df2=n-rank_full
        if df1<=0 or df2<=0:F=probability=mp.nan
        elif not r_full:
            F=mp.inf if r_red else mp.nan
            probability=mp.mpf(0) if r_red else mp.nan
        else:
            F=(max(r_red-r_full,mp.mpf(0))/df1)/(r_full/df2)
            probability=mp.betainc(mp.mpf(df2)/2,mp.mpf(df1)/2,0,df2/(df2+df1*F),regularized=True)
        return [float(F),float(probability),df1,df2,n,k,*range(k)]

def vocabulary(row):
    return list(dict.fromkeys(str(g) for t,y,g in row['parameters']['records'] if g is not None))

def codes(row,groups):
    names=vocabulary(row)
    return [names.index(g) for g in groups]

def mathematical(row):
    answer=core_mathematical(row)
    groups=list(dict.fromkeys(g for t,y,g in prepared(row)))
    return [*answer[:6],*codes(row,groups)]

def rstrings(items):
    return 'c('+','.join('NA_character_' if v is None else json.dumps(str(v),ensure_ascii=True) for v in items)+')' if items else 'character(0)'

def native_query(row):
    p=row['parameters'];records=p['records'];mapping=p.get('time_map',{})
    return f'''local({{
        raw_t<-{rstrings([r[0] for r in records])};raw_y<-{rstrings([r[1] for r in records])};raw_g<-{rstrings([r[2] for r in records])};
        map_keys<-{rstrings(list(mapping))};map_values<-suppressWarnings(as.numeric({rstrings(list(mapping.values()))}));
        mapped<-map_values[match(raw_t,map_keys)];numeric_t<-suppressWarnings(as.numeric(raw_t));
        if(length(mapping<-map_keys)>0 && any(!is.na(mapped))) t<-mapped else if(any(!is.na(numeric_t))) t<-numeric_t else {{
            matches<-regexpr('[0-9]+\\\\.?[0-9]*',raw_t,perl=TRUE);
            t<-rep(NA_real_,length(raw_t));found<-!is.na(matches) & matches>0;
            t[found]<-as.numeric(regmatches(raw_t[found],regexpr('[0-9]+\\\\.?[0-9]*',raw_t[found],perl=TRUE)));
        }};
        y<-suppressWarnings(as.numeric(raw_y));keep<-is.finite(t) & is.finite(y) & !is.na(raw_g);
        vocabulary<-unique(raw_g[!is.na(raw_g)]);names<-unique(raw_g[keep]);group_codes<-match(names,vocabulary)-1;
        t<-t[keep];y<-y[keep];group<-factor(raw_g[keep],levels=names);n<-length(y);k<-length(names);
        if(k<2 || n<3*k+1) return(c(NA_real_,NA_real_,0,0,n,k,group_codes));
        w<-2*pi/{p['period']};cosine<-cos(w*t);sine<-sin(w*t);
        reduced<-lm(y~0+group+cosine+sine);full<-lm(y~0+group+group:cosine+group:sine);
        comparison<-anova(reduced,full,test='F');df1<-full$rank-reduced$rank;df2<-df.residual(full);
        statistic<-if(df1>0 && df2>0) comparison$F[2] else NA_real_;
        probability<-if(df1>0 && df2>0) comparison$`Pr(>F)`[2] else NA_real_;
        c(statistic,probability,df1,df2,n,k,group_codes)
    }})'''

def production(row):
    import pandas as pd
    from PyFLASH.stats_extra import cosinor_group_test
    p=row['parameters'];kwargs={k:v for k,v in p.items() if k not in ['records','columns','mathematical_only','omit_period']}
    if p.get('omit_period'):kwargs.pop('period')
    answer=cosinor_group_test(pd.DataFrame(p['records'],columns=p['columns']),**kwargs)
    assert set(answer)=={'F','p','df1','df2','n','groups'}
    groups=list(dict.fromkeys(g for t,y,g in prepared(row)))
    assert answer['groups']==groups,(answer['groups'],groups)
    assert all(type(answer[key]) is int for key in ['df1','df2','n'])
    return [answer[key] for key in ['F','p','df1','df2','n']]+[len(groups),*codes(row,groups)]

def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_text(encoding='utf-8').encode()).hexdigest()!=fixture['reference_code_sha256']:
        raise ValueError('Frozen group-rhythm reference code changed.')
    current=cases()
    if current!=[{k:r[k] for k in c} for c,r in zip(current,fixture['rows'],strict=True)]:
        raise ValueError('Frozen group-rhythm input definitions changed.')
    queries=[{'key':r['key'],'code':native_query(r)} for r in current]
    if queries!=[{k:r[k] for k in q} for q,r in zip(queries,fixture['native']['rows'],strict=True)]:
        raise ValueError('Frozen raw-input native group expressions changed.')
    return fixture,queries

def execute(output):
    fixture,queries=check_identity()
    result=execute_queries(queries,output,name='group-rhythm-complete-raw-input')
    for key in ['R','webR','wasm_sha256']:
        if result[key]!=fixture['native'][key]:raise ValueError('Native group-rhythm runtime changed: '+key)
    return result
